buttonColor:
{{ 
  (() => {
    // 1. Sicheres Array holen
    const daten = Bewaesserung_Lesen.data || [];

    // 2. Aktuelle Ventilnummer aus der Liste holen
    const rawVentil = currentItem.Ventil ?? currentItem.Ventil_Links ?? currentItem.Ventil_Rechts ?? "";
    const aktivesVentil = String(rawVentil).trim();

    if (!aktivesVentil) return "#E0E0E0"; // Grau, falls kein Ventil angegeben ist

    // 3. Den NEUESTEN Eintrag suchen, der noch NICHT "fertig" ist
    const e = daten.findLast(row => {
      const vVal = String(row.Ventil || row.ventilName || "").trim();
      const status = String(row.Status || "").trim().toLowerCase();

      // Prüfen, ob die Ventilnummer übereinstimmt (Text oder Zahl)
      const matchesVentil = (vVal === aktivesVentil) || 
        (!isNaN(parseFloat(vVal)) && !isNaN(parseFloat(aktivesVentil)) && parseFloat(vVal) === parseFloat(aktivesVentil));

      // Nur berücksichtigen, wenn der Status NICHT "fertig" ist
      return matchesVentil && status !== "fertig";
    });

    // 4. Wenn kein aktiver (unfertiger) Eintrag existiert oder kein Programm gesetzt ist -> Grau
    if (!e || !e.Programm) return "#E0E0E0"; 

    // 5. Farbe nach Programm zuweisen
    const prog = String(e.Programm).trim().toLowerCase();

    switch (prog) {
      case "viel": 
        return "#1d4ed8"; // Dunkelblau

      case "wenig": 
        return "#38bdf8"; // Hellblau

      case "paletten": 
        return "#f59e0b"; // Orange / Gelb

      case "topfen": 
        return "#10b981"; // Grün

      default: 
        return "#E0E0E0"; // Grau
    }
  })() 
}}

onClick:
{{
  (async () => {
    // 1. Warten, bis der Status im Sheet auf "fertig" gesetzt wurde
    await Bewaesserung_Update_Status.run({
      "realRowIndex": List_KlimaPC.triggeredItem.rowIndex
    });

    // 2. JETZT die frischen Daten laden (das Ventil verschwindet sofort!)
    await Bewaesserung_Lesen.run();
  })()
}}
